// === Tab: mySketch ===
/**
 * GENERADOR 3D "QUANTUM MATRIX"
 * Basado en la cuadrícula 3D del usuario, expandido con Noise 3D, Orbit Control,
 * UI superpuesta en DOM, e interacciones multicapa (Mouse + Teclado).
 */

// Variables de Matriz
let gridDim = 3;       // Tamaño de la matriz (ej. 3 significa de -3 a 3)
let colorOffset = 0;   // Para cambiar las paletas de color con [C]
let tiempo = 0;        // Reloj interno
let pulsacion = 1.0;   // Factor de expansión al hacer clic

// Estados
let modoForma = 0;     // 0: Box, 1: Sphere, 2: Cylinder, 3: Torus
let esWireframe = false;
let enPausa = false;

// Variables de UI (Elementos DOM)
let uiContainer;
let sldEspaciado, sldRuido, sldTamano, sldVelocidad;
let btnModo, btnWire;

function setup() {
  // WEBGL es crucial para renderizado 3D
  createCanvas(windowWidth, windowHeight, WEBGL);
  colorMode(HSB, 360, 100, 100, 1);

  // Configuramos el panel de control flotante
  crearPanelUI();
}

function draw() {
  background(5, 5, 10); // Fondo oscuro muy profundo

  // 1. CONTROL DE CÁMARA (Magia interactiva automática)
  // Arrastrar = Orbitar | Scroll = Zoom | Clic Der + Arrastrar = Paneo
  orbitControl(2, 2, 0.1);

  // 2. LUZ Y MATERIALES
  ambientLight(0, 0, 30);
  pointLight(0, 0, 100, 0, 0, 0); // Luz en el centro
  directionalLight(0, 0, 80, 1, 1, -1);

  // 3. ACTUALIZACIÓN DE VARIABLES
  if (!enPausa) {
    tiempo += sldVelocidad.value();
  }

  // Animación suave de regreso del "Pulso" al valor normal
  pulsacion = lerp(pulsacion, 1.0, 0.1);

  let espaciadoBase = sldEspaciado.value() * pulsacion;
  let tamanoBase = sldTamano.value();
  let factorRuido = sldRuido.value();

  // Rotación global constante
  rotateX(tiempo * 0.2);
  rotateY(tiempo * 0.15);

  // 4. GENERACIÓN DE LA MATRIZ 3D
  for (let x = -gridDim; x <= gridDim; x++) {
    for (let y = -gridDim; y <= gridDim; y++) {
      for (let z = -gridDim; z <= gridDim; z++) {

        push();

        // Calcular posición en el espacio 3D
        let posX = x * espaciadoBase;
        let posY = y * espaciadoBase;
        let posZ = z * espaciadoBase;
        translate(posX, posY, posZ);

        // -- MAGIA TOUCHDESIGNER: Animación basada en Ruido 3D --
        // Calcula un valor único para cada objeto basado en su posición y el tiempo
        let variacion = noise(x * factorRuido + tiempo, y * factorRuido + tiempo, z * factorRuido);

        // Hacemos que los objetos roten sobre sí mismos
        rotateX(variacion * TWO_PI);
        rotateY(variacion * TWO_PI);

        // Cambiar el tamaño dinámicamente según el ruido
        scale(map(variacion, 0, 1, 0.2, 1.8));

        // -- COLOR MATEMÁTICO --
        // Mapeo similar al original, pero en espacio HSB para colores más ricos
        let h = map(sin(tiempo + x + y + z) + colorOffset, -2, 2, 0, 360) % 360;
        let s = map(variacion, 0, 1, 40, 100);
        let b = map(variacion, 0, 1, 50, 100);

        if (esWireframe) {
          stroke(h, s, b, 0.8);
          strokeWeight(1.5);
          noFill();
        } else {
          noStroke();
          // Leve especularidad para dar volumen
          specularMaterial(h, s, b);
          shininess(50);
        }

        // -- DIBUJO DE FORMA --
        switch (modoForma) {
          case 0: box(tamanoBase); break;
          case 1: sphere(tamanoBase * 0.6, 12, 12); break;
          case 2: cylinder(tamanoBase * 0.4, tamanoBase, 12); break;
          case 3: torus(tamanoBase * 0.4, tamanoBase * 0.15, 12, 8); break;
        }

        pop();
      }
    }
  }
}

// ----------------------------------------------------
// INTERACCIÓN DE RATÓN Y TECLADO
// ----------------------------------------------------

// Usamos doubleClicked o mouseReleased para que no choque con el arrastre de la cámara
function doubleClicked() {
  // [DOBLE CLIC]: Genera una onda de explosión (Pulse)
  pulsacion = 2.5;
}

function keyPressed() {
  let tecla = key.toLowerCase();

  if (tecla === 'm') {
    // Tecla [M]: Cambiar Forma (Box -> Sphere -> Cylinder -> Torus)
    modoForma = (modoForma + 1) % 4;
  } 
  else if (tecla === 'w') {
    // Tecla [W]: Modo Sólido / Wireframe
    esWireframe = !esWireframe;
  } 
  else if (tecla === 'c') {
    // Tecla [C]: Cambiar Espectro de Color Aleatoriamente
    colorOffset = random(10);
  }
  else if (tecla === 'p') {
    // Tecla [P]: Pausar el tiempo (congelar ondulación)
    enPausa = !enPausa;
  }
}

// ----------------------------------------------------
// CREACIÓN DE INTERFAZ HTML (Sobre el Canvas 3D)
// ----------------------------------------------------
function crearPanelUI() {
  // Contenedor principal flotante
  uiContainer = createDiv('');
  uiContainer.position(20, 20);
  // Estilo CSS directamente desde p5js
  uiContainer.style('background', 'rgba(10, 15, 20, 0.8)');
  uiContainer.style('padding', '20px');
  uiContainer.style('border', '1px solid #00F3FF');
  uiContainer.style('border-radius', '8px');
  uiContainer.style('color', '#00F3FF');
  uiContainer.style('font-family', 'monospace');
  uiContainer.style('box-shadow', '0px 0px 15px rgba(0, 243, 255, 0.2)');

  // Título
  let titulo = createP('QUANTUM MATRIX (3D)');
  titulo.style('margin-top', '0');
  titulo.style('font-weight', 'bold');
  titulo.style('border-bottom', '1px solid #00F3FF');
  titulo.style('padding-bottom', '10px');
  titulo.parent(uiContainer);

  // Función auxiliar para crear etiquetas y sliders
  function crearControl(etiqueta, min, max, val, step) {
    let div = createDiv('');
    div.style('margin-bottom', '10px');
    div.parent(uiContainer);

    let label = createSpan(etiqueta);
    label.style('display', 'block');
    label.style('margin-bottom', '5px');
    label.style('font-size', '12px');
    label.parent(div);

    let slider = createSlider(min, max, val, step);
    slider.style('width', '180px');
    slider.parent(div);
    return slider;
  }

  sldEspaciado = crearControl('Espaciado de Red:', 20, 150, 60, 1);
  sldRuido = crearControl('Distorsión Orgánica:', 0.0, 0.5, 0.2, 0.01);
  sldTamano = crearControl('Tamaño de Primitiva:', 5, 50, 18, 1);
  sldVelocidad = crearControl('Velocidad de Onda:', 0.001, 0.1, 0.02, 0.001);

  // Separador
  let sep = createDiv('<br>CONTROLES EXTRA:');
  sep.style('font-size', '12px');
  sep.style('margin-bottom', '10px');
  sep.style('color', '#aaa');
  sep.parent(uiContainer);

  // Instrucciones de Teclas
  let inst = createP(
    '[ CLICK + ARRASTRAR ] = Rotar Cámara<br>' +
    '[ SCROLL ] = Zoom<br>' +
    '[ DOBLE CLIC ] = Explosión Magnética<br>' +
    '<br>' +
    '[ M ] = Cambiar Primitiva<br>' +
    '[ W ] = Modo Wireframe / Sólido<br>' +
    '[ C ] = Mutar Paleta de Colores<br>' +
    '[ P ] = Congelar Simulacion'
  );
  inst.style('font-size', '11px');
  inst.style('color', '#FFF');
  inst.style('line-height', '1.6');
  inst.parent(uiContainer);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

